!function(e){function p(p){for(var r,i,n=p[0],o=p[1],d=p[2],s=0,g=[];s<n.length;s++)i=n[s],Object.prototype.hasOwnProperty.call(m,i)&&m[i]&&g.push(m[i][0]),m[i]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(e[r]=o[r]);for(c&&c(p);g.length;)g.shift()();return a.push.apply(a,d||[]),t()}function t(){for(var e,p=0;p<a.length;p++){for(var t,i=a[p],n=!0,o=1;o<i.length;o++)t=i[o],0!==m[t]&&(n=!1);n&&(a.splice(p--,1),e=r(r.s=i[0]))}return e}function r(p){if(i[p])return i[p].exports;var t=i[p]={i:p,l:!1,exports:{}};return e[p].call(t.exports,t,t.exports,r),t.l=!0,t.exports}var i={},m={68:0},a=[];r.m=e,r.c=i,r.d=function(e,p,t){r.o(e,p)||Object.defineProperty(e,p,{enumerable:!0,get:t})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,p){if(1&p&&(e=r(e)),8&p)return e;if(4&p&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(r.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&p&&"string"!=typeof e)for(var i in e)r.d(t,i,function(p){return e[p]}.bind(null,i));return t},r.n=function(e){var p=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(p,"a",p),p},r.o=function(e,p){return Object.prototype.hasOwnProperty.call(e,p)},r.p="";var n=window.webpackJsonp=window.webpackJsonp||[],o=n.push.bind(n);n.push=p,n=n.slice();for(var d=0;d<n.length;d++)p(n[d]);var c=o;a.push([176,0]),t()}({176:function(e,p,t){"use strict";t.r(p);var r=t(0);Object(r.a)("de","army",t(177),t(1))},177:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"军用摩托车","link":"de_army#de_army_mtm"}],"model":"宝马军用摩托车","description":"<p>二战中，德军拥有数量众多的军用摩托车，利用摩托车的轻便、机动和良好的越野性能，这些军用摩托车在战争中不但担任了通信传令、部队联络、侦察伏击和后勤救护等任务，德军还专门用摩托车组成了作战部队，担任战场突击、机动作战与迂回包围等战斗任务。</p><p>二战中德军的军用摩托车主要由宝马（BMW）、春达普（Zϋndapp）、NSU和DKW等公司所生产，其中以“宝马”和“春达普”公司生产的数量最多。这些军用摩托车可分为轻型、中型和重型三种，中、重型摩托车可附带挎斗成为三轮摩托车，每车可坐3人（含驾驶员），挎斗中的德军一般会配备一挺MG13或MG34机枪（备弹150发），一般会装备在德军摩托化部队中，直接进入战场参与战斗，而轻型摩托车则以单车单人驾驶，配属给中、高级指挥部的通讯班，负责传令、联络等任务。</p><p>宝马公司生产的军用摩托车型号众多，主要有R4、R11、R12、R35、R61与R75等，这些摩托车从二战前就已研制并已实现量产，除个别型号（如R35）是轻型车外，宝马大多型号的摩托车都属重型车，配双缸风冷式发动机，带4速（带倒挡）变速箱，动力强劲，可算是各参战国中性能最优秀的摩托车。在德军部队配备的摩托车中，宝马军用摩托车数量是相当多的，在战场上屡见德军驾驶它们执行各种任务与直接在前线作战的身影，是德军一支不可忽视的力量。</p>","part1title":"主要型号","part1description":"","part1content":[{"image":"imgs/de/army/de_army_mtmBMW_11.jpg","description":"<h6>宝马（BMW）R75型军用摩托车</h6><p>该型车属重型摩托车，是宝马系列摩托车中最出名的一种，该车机动性好，越野能力强，其带斗后可搭载3名士兵，并配备一挺MG34（早期为MG13）机枪，因此具有很强的突击力和战斗力，R 35军用摩托车大部分装备给德军装甲师，作战斗部队使用，其在环境恶劣的苏德战场与北非战场上表现了良好的机动性与可靠性，深受德军的喜爱。该型车从1940年开始量产，直到1944年止，一共生产了约18000辆，也是德军中装备数量最多的摩托车之一。</p><p>技术参数：</p><p>车长：2.4米，车宽：1.73米，车高：1.0米；</p><p>车重：400公斤，战斗全重：820公斤；</p><p>最高时速：92公里/小时；</p><p>发动机每100公里油耗：公路6.7升，越野9升；</p><p>油箱容量：24升；</p><p>公路最大行程（满载油缸）：360公里。</p>","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_16.jpg","description":"<h6>宝马（BMW）R12型军用摩托车</h6><p>该型车车体轻，车速高，越野性能也好，大多会挂上边厢装备给德军装甲师的摩托化部队，作战斗部队用，也是德军装备数量较多的一种宝马摩托车。</p><p>技术参数：</p><p>车长：2.1米，车宽：0.9米，车高：0.94米；</p><p>车重：188公斤；</p><p>最高时速：100公里/小时；</p><p>发动机型号：BMW212，功率：18马力；</p><p>每100公里油耗：公路3.5～4升，越野4.5～5升；</p><p>油箱容量：14升；</p><p>公路最大行程（满载油缸）：350公里。</p>","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_24.jpg","description":"<h6>宝马（BMW）R35型军用摩托车</h6><p>宝马（BMW）R35是一种轻型摩托车，其车身轻，车速高，由于是轻型摩托车，所以R35一般都不会挂边厢，通常由单人驾驶，担任通讯、传令与联络任务。</p><p>技术参数：</p><p>车长：2.0米，车宽：0.8米，车高：0.95米；</p><p>车重：165公斤；</p><p>最高时速：100公里/小时；</p><p>发动机型号：BMW，功率：14马力；</p><p>油箱容量：12升；</p><p>公路最大行程（满载油缸）：340公里。</p>","caption":""}],"part2title":"战场上的宝马军用摩托车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_mtmBMW_12.jpg","description":"1943年秋天，东线苏联战场，隶属德军“大德意志”装甲掷弹兵师第1摩托化警卫连的一辆宝马BMW R75军用摩托车。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_13.jpg","description":"一队由宝马BMW R75组成的军用摩托车队在行进中，摩托车手都戴着护目镜，车后有备用轮胎，车斗架着MG34机枪，显然是一支战斗部队；R75由于是重型摩托车，因此车轮较宽，特别醒目。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_14.jpg","description":"1942年夏天，东线苏联战场，德军第24装甲师第24摩托化营的一支摩托车队正在集结地准备出发，该队配备的都是宝马BMW R75重型摩托车。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_15.jpg","description":"1944年，西线战场意大利，一辆隶属德军第1伞兵师的宝马BMW R75重型摩托车，车上士兵已跳下车准备投入战斗。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_17.jpg","description":"1940年5月，西线战场法国，隶属德军第2装甲师第2摩托车警卫营的一辆宝马BMW R12重型摩托车。车头有救护车的红十字标志。由于摩托车具有很好的机动性和越野性，因此经常会被作转运战场伤员用。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_18.jpg","description":"1941年，驾驶着宝马BMW R12军用摩托车在鲁布兰（RuBland）地区巡逻的德军宪兵队。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_19.jpg","description":"1941年希腊地区，德军一支宝马BMW R12军用摩托车部队在集结地准备出发，摩托兵们都穿着长雨衣，以在高速行驶中抵御寒风。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_20.jpg","description":"摩托车兵由于经常要执行奔袭和包抄等战斗任务，长途行驶使他们身体与精神都会十分疲劳，因此在行进途中都会利用停车时间进行休息睡眠。图中最前面一辆宝马BMW R12军用摩托车上一名德军士兵身上挂满武器和军用品，正憇睡在车斗中。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_21.jpg","description":"1941年秋天，东线苏联战场，德军“克莱斯特”装甲集团的一辆宝马BMW R12摩托车陷进泥泞中，几名德军正在努力将它推出。当时，由于苏联的道路状况普遍很差，德军摩托车在路上经常会出现这种情况。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_22.jpg","description":"1941年4月，巴尔干半岛希腊，隶属德军第5装甲师第55摩托化营的一队宝马BMW R12摩托车队正沿着铁路行进。摩托车巧妙地将铁轨置于车身与边厢的两轮之间，可见德军的摩托车手还是掌握有较好的驾驶技能。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_23.jpg","description":"1939年9月，波兰战场，德军第4装甲师第12警卫团的一辆宝马BMW R12摩托车正牵引着一门75mm口径火炮上前线。事实上，用摩托车牵引火炮的情况是比较少见的，只有在无牵引车而战场上又急需时才会这样做。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_25.jpg","description":"1941年夏天，东线苏联战场，驾驶宝马BMW R35轻型摩托车的德军传令兵正在路上观看写在油桶上的临时路标。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_26.jpg","description":"1941年秋天，东线苏联战场，一队传令兵驾驶宝马BMW R35轻型摩托车和宝马BMW R12军用摩托车随德军装甲部队一起通过被占领的城市继续向前线前进。","caption":""},{"image":"imgs/de/army/de_army_mtmBMW_27.jpg","description":"1941年秋天，东线苏联战场，德军冯·克鲁格元帅正在给他的两名传令兵安排任务，该传令兵驾驶的是一辆宝马BMW R35轻型摩托车。","caption":""}]}')}});